create table if not exists public.students(student_code text primary key,grade smallint not null check(grade between 1 and 6),class_no smallint not null check(class_no between 1 and 99),seat_no smallint not null check(seat_no between 1 and 999),last_seen timestamptz not null default now());create table if not exists public.learning_events(id bigint generated always as identity primary key,student_code text not null references public.students(student_code) on delete cascade,event_type text not null check(event_type in ('question','session')),question_id text,prompt text,answer text,correct boolean,retries smallint default 0,help boolean default false,manual_confirm boolean default false,volume text,total smallint,correct_no_help smallint,help_count smallint,retry_count smallint,created_at timestamptz not null default now());create index if not exists learning_events_student_created_idx on public.learning_events(student_code,created_at desc);alter table public.students enable row level security;alter table public.learning_events enable row level security;